class Solution:
    def addTwoNumbers(self, l1: Optional[ListNode], l2: Optional[ListNode]) -> Optional[ListNode]:

        dummy = ListNode(0)
        curr = dummy
        carry = 0

        while l1 is not None or l2 is not None or carry != 0:
            if l1 is not None:
                v1 = l1.val
            else:
                v1 = 0

            if l2 is not None:
                v2 = l2.val
            else:
                v2 = 0

            ttl = v1 + v2 + carry
            carry = ttl // 10
            val = ttl % 10

            curr.next = ListNode(val)
            curr = curr.next

            if l1 is not None:
                l1 = l1.next
            if l2 is not None:
                l2 = l2.next

        return dummy.next

