class Solution:
    # @param two ListNodes
    # @return a ListNode
    def mergeTwoLists(self, l1, l2):
        if l1 == None:
            return l2
        if l2 == None:
            return l1
        dummy = ListNode(0)
        tmp = dummy
        while l1 and l2:
            if l1.val <= l2.val:
                tmp.next = l1
                l1 = l1.next
                tmp = tmp.next
            else:
                tmp.next = l2
                l2 = l2.next
                tmp = tmp.next
        if l2 == None:
            tmp.next = l1
        else:
            tmp.next = l2
        return dummy.next

class Solution:
    def generateParenthesis(self, n: int) -> List[str]:

        res = []
        path = []

        self.backtrack(0, 0, n, path, res)
        return res

    def backtrack(self, left, right, n, path, res):

        if len(path) == 2 * n:
            res.append("".join(path))
            return

        if left < n:
            path.append("(")
            self.backtrack(left+1, right, n, path, res)
            path.pop()

        if right < left:
            path.append(")")
            self.backtrack(left, right+1, n, path, res)
            path.pop()

class Solution(object):
    def removeDuplicates(self, nums):
        slow = 0
        for fast in range(0, len(nums)):
            if nums[slow] != nums[fast]:
                slow += 1
                nums[slow] = nums[fast]
        return len(nums[0:slow+1])

class Solution(object):
    def removeElement(self, nums, val):

        slow = 0
        for fast in range(0, len(nums)):
            if nums[fast] != val:
                nums[slow] = nums[fast]
                slow += 1
        return len(nums[0:slow])

class Solution:
    def search(self, nums: List[int], target: int) -> int:

        pivot = self.findPivotIndex(nums)

        if nums[pivot] <= target <= nums[len(nums)-1]:
            return self.binarySearch(nums, pivot, len(nums)-1, target)
        else:
            return self.binarySearch(nums, 0, pivot-1, target)


    def findPivotIndex(self, nums: List[int]) -> int:
        left, right = 0, len(nums) - 1

        while left <= right:                
            mid = left + (right - left) // 2

            if nums[mid] > nums[right]:
                left = mid + 1
            elif nums[mid] < nums[right]:
                right = mid
            else:
                right -= 1

        return left

    def binarySearch(self, nums: List[int], left, right, target):
        while left <= right:
            mid = left + (right - left) // 2
            if nums[mid] == target:
                return mid
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return -1

