class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:


        leftBound = self.leftBound(nums, target)
        rightBound = self.rightBound(nums, target)

        return [leftBound, rightBound]

    def leftBound(self, nums: List[int], target: int) -> int:
        left, right = 0, len(nums)-1
        while left <= right:
            mid = left + (right - left) // 2
            if nums[mid] == target:
                right = mid - 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        if left < 0 or left >= len(nums):
            return -1 
        if nums[left] == target:
            return left
        else:
            return -1

    def rightBound(self, nums: List[int], target: int) -> int:
        left, right = 0, len(nums)-1
        while left <= right:
            mid = left + (right - left) // 2
            if nums[mid] == target:
                left = mid + 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        if right < 0 or right >= len(nums):
            return -1
        if nums[right] == target:
            return right
        else:
            return -1

class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        firstBound = self.findBound(nums, target, isFirst = True)

        if firstBound == -1:
            return [-1, -1]

        lastBound = self.findBound(nums, target, isFirst = False)

        return [firstBound, lastBound]


    def findBound(self, nums: List[int], target: int, isFirst: bool) -> int:
        left, right = 0, len(nums)-1
        candidate = -1

        while left <= right:
            mid = left + (right - left) // 2
            if nums[mid] == target:
                candidate = mid
                if isFirst == True:
                    right = mid - 1
                else:
                    left = mid + 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return candidate

class Solution:
    def searchRange(self, nums: List[int], target: int) -> List[int]:
        firstBound = self.findBound(nums, target, isFirst=True)
        if firstBound == -1:
            return [-1, -1]
        else:
            lastBound = self.findBound(nums, target, isFirst=False)
            return [firstBound, lastBound]

    def findBound(self, nums: List[int], target: int, isFirst: bool) -> int:
        left, right = 0, len(nums)-1
        bound = -1

        while left <= right:
            mid = left + (right-left) // 2
            if nums[mid] == target:
                bound = mid
                if isFirst:
                    right = mid - 1
                else:
                    left = mid + 1
            elif nums[mid] > target:
                right = mid - 1
            else:
                left = mid + 1
        return bound

