class Solution:
    def isValidSudoku(self, board: List[List[str]]) -> bool:
        n = len(board)
        rows = []
        cols = []
        boxes = []

        for i in range(0, n):
            rows.append(set())
            cols.append(set())
            boxes.append(set())

        for r in range(0, n):
            for c in range(0, n):
                val = board[r][c]
                if val == ".":
                    continue
                box = (r//3)*3 + c//3

                if val not in rows[r]: 
                    rows[r].add(val)
                else:
                    return False

                if val not in cols[c]: 
                    cols[c].add(val)
                else:
                    return False

                if val not in boxes[box]: 
                    boxes[box].add(val)
                else:
                    return False

        return True

class Solution:
    def combinationSum(self, candidates: List[int], target: int) -> List[List[int]]:
        res = []
        path = []
        self.dfs(candidates, target, 0, path, res)
        return res


    def dfs(self, candidates, target, start, path, res):
        if target == 0:
            res.append(path[:])
            return 

        if target < 0:
            return 

        for c in range(start, len(candidates)):
            path.append(candidates[c])
            self.dfs(candidates, target-candidates[c], c, path, res)
            path.pop()

