class Solution:
    def groupAnagrams(self, strs: List[str]) -> List[List[str]]:
        count = {}
        for s in strs:
            key = "".join(sorted(s))
            if key not in count:
                count[key] = [s]
            else:
                count[key].append(s)
        return list(count.values())

class Solution:
    def mySqrt(self, x: int) -> int:

        left, right = 0, x
        res = 0


        while left <= right:
            mid = left + (right - left) // 2

            if mid * mid == x:            
                return mid
            elif mid * mid > x:
                right = mid - 1
            elif mid * mid < x:
                res = mid
                left = mid + 1


        return res

