class Solution:
    def zigzagLevelOrder(self, root: Optional[TreeNode]) -> List[List[int]]:
        if not root:
            return []

        q = collections.deque([root])
        ans = []
        depth = 0

        while q:
            size = len(q)
            vals = []

            for _ in range(size):
                node = q.popleft()
                vals.append(node.val)

                if node.left: q.append(node.left)
                if node.right: q.append(node.right)

            if depth % 2 == 1:
                vals = vals[::-1]

            ans.append(vals)
            depth += 1
        return ans

