            return []

        q = collections.deque()
        ans = []
        q.append(root)
        even = False

        while q:
            vals = []

            for _ in range(0, len(q)):
                node = q.popleft()
                vals.append(node.val)

                if node.left: q.append(node.left)
                if node.right: q.append(node.right)

            even = not even
            if even == False:
                vals = vals[::-1]

            ans.append(vals)
        return ans

