class Solution:
    def generate(self, numRows: int) -> List[List[int]]:

        arr = [[1]]

        for i in range(1, numRows):
            lastRow = arr[-1]
            newRow = [1]
            for j in range(len(lastRow)-1):
                newRow.append(lastRow[j]+lastRow[j+1])
            newRow.append(1)
            arr.append(newRow)

        return arr

class Solution:
    def generate(self, numRows: int) -> List[List[int]]:
        if numRows == 1:
            return [[1]]

        if numRows == 2:
            return [[1], [1, 1]]

        preProb = self.generate(numRows-1)
        subProb = self.subProb(preProb[-1])
