        closest = root.val

        while root:
            if abs(root.val - target) < abs(closest - target) or ((abs(root.val - target) == abs(closest - target)) and (root.val < closest)):
                closest = root.val

            if target < root.val:
                root = root.left
            elif target > root.val:
                root = root.right
            elif target == root.val:
