        while lowVal < highVal:
            midVal = lowVal + (highVal - lowVal) // 2
            cnt = self.countLessEqual(matrix, midVal)

            if cnt < k:
                lowVal = midVal + 1
            else:
                highVal = midVal
        return lowVal

    def countLessEqual(self, matrix: List[List[int]], midVal: int) -> int:
        n = len(matrix)
