class Solution:
    def calcEquation(self, equations: List[List[str]], values: List[float], queries: List[List[str]]) -> List[float]:
        graph = collections.defaultdict(list)

        for (u, v), value in zip(equations, values):
            graph[u].append((v, value))
            graph[v].append((u, 1.0/value))

        res = []
        for start, end in queries:
            if start not in graph or end not in graph:
                res.append(-1.0)
                continue

            found = False
            stack = [(start, 1.0)]
            visited = set()

            while stack:
                curr, currProduct = stack.pop()

                if curr == end:
                    res.append(currProduct)
                    found = True
                    break

                visited.add(curr)

                for neighbor, weight in graph[curr]:
                    if neighbor not in visited:
                        stack.append((neighbor, currProduct * weight))
            if not found:
                res.append(-1.0)

        return res

class Solution:
    def calcEquation(self, equations: List[List[str]], values: List[float], queries: List[List[str]]) -> List[float]:
        graph = collections.defaultdict(list)

        for (u, v), val in zip (equations, values):
            graph[u].append((v, val))
            graph[v].append((u, 1.0/val))

        res = []
        for start, end in queries:
            if start not in graph or end not in graph:
                res.append(-1.0)
            else:
                res.append(self.dfs(start, end, set(), graph))

        return res

    def dfs(self, curr, target, visited, graph):
        if curr == target:
            return 1.0

        visited.add(curr)

        for neighbor, weight in graph[curr]:
            if neighbor not in visited:
                res = self.dfs(neighbor, target, visited, graph)
                if res != -1.0:
                    return weight * res

        return -1.0

class Solution:
    def findNthDigit(self, n: int) -> int:
        length = 1
        count = 9
        start = 1

        while n > length * count:
            n -= length * count
            length += 1
            start *= 10
            count *= 10

        num = start + (n-1) // length
        idx = (n-1) % length
        return int(str(num)[idx])

