#     def __init__(self, val=0, left=None, right=None):
#         self.val = val
#         self.left = left
#         self.right = right
class Solution:
    def sumOfLeftLeaves(self, root: Optional[TreeNode]) -> int:
        if not root:
            return 0

        self.res = 0
        self.traverse(root, None)
        return self.res

    def traverse(self, node: Optional[TreeNode], prev: Optional[TreeNode]):
        if not node:
            return 

        if node.left is None and node.right is None and prev is not None and prev.left == node:
            self.res += node.val

        self.traverse(node.left, node)
        self.traverse(node.right, node)

class Solution:
    def longestPalindrome(self, s: str) -> int:
        dic = {}
        for i in s:
            if i in dic:
                dic[i] += 1
            else:
                dic[i] = 1

        res = 0
        hasOdd = False
        for val, cnt in dic.items():
            if cnt % 2 == 0:
                res += cnt
            else:
                res += (cnt - 1)
                hasOdd = True

        if hasOdd == True:
            return res+1
        else:
            return res

class Solution:
    def numberOfArithmeticSlices(self, nums: List[int]) -> int:

        size = len(nums)
        left, right = 0, 0
        res = []
        ttl = 0

        while right < size:
            res.append(nums[right])
            right += 1

            while len(res) >= 3 and self.calcDiff(res) is False:
                del res[0]
                left += 1

            if len(res) >= 3:
                ttl += len(res) - 2

        return ttl


    def calcDiff(self, nums: List[int]) -> bool:
        tag = True
        diff = nums[1] - nums[0]
        for i in range(0, len(nums)-1):
            if nums[i+1] - nums[i] != diff:
                tag = False
                break
        return tag

