    def dfs(self, grid, r, c):
        if (r < 0 or r >= len(grid) or
            c < 0 or c >= len(grid[0]) or
            grid[r][c] == 0):
            return 1

        if grid[r][c] == 2:
            return 0

        grid[r][c] = 2

        return (self.dfs(grid, r, c+1) +
                self.dfs(grid, r, c-1) +
                self.dfs(grid, r-1, c) +
                self.dfs(grid, r+1, c))

