            if heaters[mid] == h:
                return 0
            elif heaters[mid] > h:
                right = mid - 1
            else:
                left = mid + 1

        if toLeft == True:
            if right < 0:
                return float('inf')
            return h - heaters[right]
        else:
            if left >= len(heaters):
                return float('inf')
            return heaters[left] - h

