        while left < right:
            if s[left] != s[right]:
                leftCheck = self.ifPalindrome(s, left+1, right)
                rightCheck = self.ifPalindrome(s, left, right-1)
                return leftCheck or rightCheck

            left += 1
            right -=1
        return True



    def ifPalindrome(self, s: str, left: int, right: int) -> bool:

        while left < right:
            if s[left] == s[right]:
                left += 1
                right -= 1
            else:
                return False
                break
        return True

class Solution:
    def calPoints(self, operations: List[str]) -> int:
        stack = []
        for num in operations:

            if num == 'D':
                prev = stack.pop()
                stack.append(prev)
                stack.append(prev * 2)

            elif num == 'C':
                stack.pop()

            elif num == '+':
                prev1 = stack.pop()
                prev2 = stack.pop()
                stack.append(prev2)
                stack.append(prev1)
                stack.append(prev1 + prev2)

            else:
                stack.append(int(num))

        return sum(stack)

