    def bfs(self, grid, r, c):
        queue = collections.deque([(r, c)])
        cnt = 1
        grid[r][c] = 0

        while queue:
            currR, currC = queue.popleft()

            for dr, dc in ((0, 1), (0, -1), (1, 0), (-1, 0)):
                nxtR, nxtC = currR + dr, currC + dc

                if (0 <= nxtR < len(grid) and
                    0 <= nxtC < len(grid[0]) and
                    grid[nxtR][nxtC] == 1):
                    queue.append((nxtR, nxtC))
                    grid[nxtR][nxtC] = 0
                    cnt += 1
        return cnt

