        for i in range(n):
            length = min(m, n-i)
            currLen = self.getMaxLen(nums1, nums2, i, 0, length)
            ret = max(ret, currLen)

        for i in range(m):
            length = min(n, m-i)
            currLen = self.getMaxLen(nums1, nums2, 0, i, length)
