import collections

class Solution:
    def networkDelayTime(self, times: list[list[int]], n: int, k: int) -> int:

        ## dfs

        self.graph = collections.defaultdict(list)
        for u, v, w in times:
            self.graph[u].append((v, w))

        for u in self.graph:
            self.graph[u].sort(key=lambda x: x[1])

        self.dist = [float('inf')] * (n + 1)

        self.dfs(k, 0)

        max_dist = max(self.dist[1:])
        return max_dist if max_dist != float('inf') else -1

    def dfs(self, node: int, current_time: int):

        if current_time >= self.dist[node]:
            return

        self.dist[node] = current_time

        if node in self.graph:
            for neighbor, weight in self.graph[node]:
                self.dfs(neighbor, current_time + weight)

class Solution:
    def networkDelayTime(self, times: list[list[int]], n: int, k: int) -> int:

        # bfs（spfa变体）

        graph = collections.defaultdict(list)
        for u, v, w in times: graph[u].append((v, w))
        dist = [float('inf')] * (n + 1)
        dist[k] = 0
        queue = collections.deque([k])

        while queue:
            u = queue.popleft()
            for v, w in graph[u]:
                if dist[u] + w < dist[v]:
                    dist[v] = dist[u] + w
                    queue.append(v)

        res = max(dist[1:])
        return res if res < float('inf') else -1

import heapq, collections

class Solution:
    def networkDelayTime(self, times: list[list[int]], n: int, k: int) -> int:

        # heap 优化djikstra

        graph = collections.defaultdict(list)
        for u, v, w in times:
            graph[u].append((v, w))

        pq = [(0, k)] # (距离, 节点)
        dist = {}

        while pq:
            d, u = heapq.heappop(pq)
            if u in dist: continue
            dist[u] = d
            for v, w in graph[u]:
                if v not in dist:
                    heapq.heappush(pq, (d + w, v))

        return max(dist.values()) if len(dist) == n else -1

class Solution:
    def networkDelayTime(self, times: List[List[int]], n: int, k: int) -> int:

        # 朴素djikstra

        graph = [[float('inf')] * n for _ in range(n)]
        for u, v, w in times:
            graph[u-1][v-1] = min(graph[u-1][v-1], w)

        dist = [float('inf')]  * n
        dist[k-1] = 0
        visited = [False] * n

        for _ in range(n):
            x = -1
            for y in range(n):
                if not visited[y] and (x == -1 or dist[y] < dist[x]):
                    x = y

            if dist[x] == float('inf'):
                break

            visited[x] = True

            for y in range(n):
                if graph[x][y] != float('inf'):
                    dist[y] = min(dist[y], dist[x] + graph[x][y])

        maxDist = max(dist)
        if maxDist < float('inf'):
            return int(maxDist)
        else:
            return -1

