class Solution:
    def nextGreatestLetter(self, letters: List[str], target: str) -> str:
        index =  self.helper(letters, target, 0, len(letters)-1)
        return letters[index % len(letters)]

    def helper(self, letters: List[str], target: int, left: int, right: int) -> int:
        if left > right:
            return left

        mid = left + (right - left) // 2

        if letters[mid] > target:
            return self.helper(letters, target, left, mid-1)
        elif letters[mid] <= target:
            return self.helper(letters, target, mid+1, right)

class Solution:
    def nextGreatestLetter(self, letters: List[str], target: str) -> str:

        left, right = 0, len(letters)-1
        while left < right:
            mid = left + (right - left) // 2
            if letters[mid] > target:
                right = mid
            elif letters[mid] <= target:
                left = mid + 1

        if letters[left] > target:
            return letters[left]
        else:
            return letters[0]

class Solution:
    def minCostClimbingStairs(self, cost: List[int]) -> int:

        self.cost = cost
        self.n = len(cost)
        self.dp = [-1] * (self.n + 1)

        return min(self.recursion(self.n - 1), self.recursion(self.n - 2)) 


    def recursion(self, n: int) -> int:
        if n == 0:
            return self.cost[0]

        if n == 1:
            return self.cost[1]

        if self.dp[n] != -1:
            return self.dp[n]

        self.dp[n] = min(self.recursion(n-1), self.recursion(n-2)) + self.cost[n]
        return self.dp[n]

