class Solution:
    def lemonadeChange(self, bills: List[int]) -> bool:


        rem5 = 0
        rem10 = 0

        for m in bills:

            if m == 5:
                rem5 += 1

            if m == 10:
                if rem5 <= 0:
                    return False
                rem5 -= 1
                rem10 += 1

            if m == 20:
                if rem5 > 0 and rem10 > 0:
                    rem5 -= 1
                    rem10 -= 1
                elif rem5 >= 3:
                    rem5 -= 3
                else:
                    return False      

        return True

class Solution:
    def fairCandySwap(self, aliceSizes: List[int], bobSizes: List[int]) -> List[int]:
        suma = sum(aliceSizes)
        sumb = sum(bobSizes)
        sumt = (suma + sumb) / 2

        seen = set(bobSizes)

        for i in aliceSizes:
            res = sumt - suma + i
            if res in seen:
                return [i, res]
        return -1

