    def totalFruit(self, fruits: List[int]) -> int:


        left, right = 0, 0
        res = {}
        maxSum = 0
        while right < len(fruits):
            res[fruits[right]] = 1 + res.get(fruits[right], 0)
            right += 1

            while len(res) > 2:
                res[fruits[left]] -= 1

                if res[fruits[left]] == 0:
                    del res[fruits[left]]

                left += 1

            maxSum = max(maxSum, right-left)
        return maxSum

class Solution(object):
    def sortArrayByParity(self, nums):
        """
        :type nums: List[int]
        :rtype: List[int]
        """
        i = 0
        j = len(nums)-1
        while i < j:
            if nums[i] % 2 != 0 and nums[j] % 2 == 0:
                nums[i], nums[j] = nums[j], nums[i]
                i += 1
                j -= 1
            elif nums[i] % 2 == 0:
                i += 1
            elif nums[j] % 2 != 0:
                j -= 1

        return nums

class Solution(object):
    def sortArrayByParityII(self, nums):
        n = len(nums)
        # even_ptr 负责在偶数位上寻找“错位的奇数”
        even_ptr = 0
        # odd_ptr 负责在奇数位上寻找“错位的偶数”
        odd_ptr = 1

        while even_ptr < n and odd_ptr < n:
            # 1. even_ptr 不断前进，直到找到一个奇数
            while even_ptr < n and nums[even_ptr] % 2 == 0:
                even_ptr += 2

            # 2. odd_ptr 不断前进，直到找到一个偶数
            while odd_ptr < n and nums[odd_ptr] % 2 == 1:
                odd_ptr += 2

            # 3. 如果两个指针都还没越界，说明都找到了目标，进行交换
            if even_ptr < n and odd_ptr < n:
                nums[even_ptr], nums[odd_ptr] = nums[odd_ptr], nums[even_ptr]

        return nums

class Solution(object):
    def sortArrayByParityII(self, nums):
        """
        :type nums: List[int]
        :rtype: List[int]
        """
        i = 0
        j = 1
        while i < len(nums) and j < len(nums):
            if nums[i] % 2 != 0 and nums[j] % 2 == 0:
                nums[i], nums[j] = nums[j], nums[i]
                i += 2
                j += 2
            elif nums[i] % 2 == 0:
                i += 2
            elif nums[j] % 2 != 0:
                j += 2
        return nums

class Solution:
    def numSubarraysWithSum(self, nums: List[int], goal: int) -> int:

        return self.atMost(nums, goal) - self.atMost(nums, goal-1)


    def atMost(self, nums: List[int], k: int) -> int:
        if k < 0:
            return 0

        left, right = 0, 0
        res = 0
        cnt = 0

        while right < len(nums):
            res += nums[right]
            right += 1

            while res > k:
                res -= nums[left]
                left += 1

            cnt += (right - left)

        return cnt

