        maxHeap = []
        for s in stones:
            heapq.heappush(maxHeap, -s)

        while len(maxHeap)>1:
            x = heapq.heappop(maxHeap)
            y = heapq.heappop(maxHeap)

            if x != y:
                heapq.heappush(maxHeap, x-y)

        if not maxHeap:
            return 0
        else:
            return -maxHeap[0]

