class Solution:
    def checkIfPrerequisite(self, numCourses: int, prerequisites: List[List[int]], queries: List[List[int]]) -> List[bool]:
        indegree = [0] * numCourses
        adj = [[] for _ in range(numCourses)]
        isPre = [set() for _ in range(numCourses)]

        for u, v in prerequisites:
            adj[u].append(v)
            indegree[v] += 1
            isPre[v].add(u)

        queue = collections.deque([i for i in range(numCourses) if indegree[i] == 0])

        while queue:
            u = queue.popleft()
            for v in adj[u]:
                isPre[v].update(isPre[u])

                indegree[v] -= 1
                if indegree[v] == 0:
                    queue.append(v)

        return [u in isPre[v] for u, v in queries]

class Solution:
    def checkIfPrerequisite(self, numCourses: int, prerequisites: List[List[int]], queries: List[List[int]]) -> List[bool]:
        adj = [[] for _ in range(numCourses)]
        for u, v in prerequisites:
            adj[u].append(v)

        memo = [[-1] * numCourses for _ in range(numCourses)]

        res = []
        for u, v in queries:
            if self.canReach(u, v, adj, memo):
                res.append(True)
            else:
                res.append(False)
        return res

    def canReach(self, u, v, adj, memo):
        if memo[u][v] != -1:
            return memo[u][v] == 1

        for neighbor in adj[u]:
            if neighbor == v or self.canReach(neighbor, v, adj, memo):
                memo[u][v] = 1
                return True

        memo[u][v] = 0
        return False

