class Solution(object):
    def decrypt(self, code, k):
        """
        :type code: List[int]
        :type k: int
        :rtype: List[int]
        """


        n = len(code)
        next_win = sum(code[1: (k % n) + 1]) + sum(code[:]) * (k // n)
        befr_win = sum(code[n - (abs(k) % n): n]) + sum(code[:]) * (abs(k) // n)
        arr = [0] * n

        if k == 0:
            arr[0] = 0
        elif k > 0:
            arr[0] = next_win
        elif k < 0:
            arr[0] = befr_win


        for i in range(1, len(code)):
            if k == 0:
                arr[i] = 0
            elif k > 0:
                next_win = next_win + code[(i + k) % n] - code[i]
                arr[i] = next_win
            elif k < 0:
                befr_win = befr_win + code[i-1] - code[i - 1 - (abs(k) % n)]
                arr[i] = befr_win
        return arr

class Solution:
    def maxRepeating(self, sequence: str, word: str) -> int:
        self.sequence = sequence
        self.word = word
        self.n = len(sequence)
        self.m = len(word)

        self.memo = {}

        maxk = 0
        for i in range(self.n):
            maxk = max(maxk, self.recursion(i))

        return maxk


    def recursion(self, i: int) -> int:

        if i < self.m - 1:
            return 0

        if i in self.memo:
            return self.memo[i]

        curr = self.sequence[i - self.m + 1: i + 1]

        if curr == self.word:
            res = 1 + self.recursion(i - self.m)
        else:
            res = 0

        self.memo[i] = res
        return res

class Solution:
    def maxRepeating(self, sequence: str, word: str) -> int:
        n = len(sequence)
        m = len(word)
        k = 0

        left = 0 
        right = 0

        while left < n:
            right = left 
            curr = 0

            while right + m <= n:
                if sequence[right: right+m] == word:
                    curr += 1
                    right += m
                else:
                    break
            k = max(k, curr)
            left += 1
        return k

