        boxTypes.sort(key=lambda x: x[1], reverse=True)

        size = 0
        units = 0

        for i in range(0, len(boxTypes)):

            if size +  boxTypes[i][0] > truckSize:
                units += (truckSize - size) * boxTypes[i][1]
