class Solution:
    def findAllRecipes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        graph = {}
        for i in range(len(recipes)):
            graph[recipes[i]] = ingredients[i]

        suppSet = set()
        for s in supplies:
            suppSet.add(s)

        status = {}
        res = []

        for i in range(len(recipes)):
            target = recipes[i]
            if self.dfs(target, graph, suppSet, status):
                res.append(target)

        return res

    def dfs(self, name, graph, suppSet, status):
        if name in suppSet:
            return True

        if name not in graph:
            return False

        if name in status:
            currState = status[name]
            if currState == 1:
                return False
            if currState == 2:
                return True
            if currState == 3:
                return False

        status[name] = 1

        needed = graph[name]

        for i in range(len(needed)):
            ing = needed[i]
            if self.dfs(ing, graph, suppSet, status) == False:
                status[name] = 3
                return False

        status[name] = 2
        return True

class Solution:
    def findAllRecipes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        graph = collections.defaultdict(list)
        indegree = collections.defaultdict(int)

        for ingredientList, recipt in zip(ingredients, recipes):
            indegree[recipt] = len(ingredientList)
            for ing in ingredientList:
                graph[ing].append(recipt)

        queue = collections.deque(supplies)
        recipeSet = set(recipes)
        ans = []

        while queue:
            curr = queue.popleft()

            if curr in recipeSet:
                ans.append(curr)

            for nextRecipt in graph[curr]:
                indegree[nextRecipt] -= 1
                if indegree[nextRecipt] == 0:
                    queue.append(nextRecipt)
        return ans

class Solution:
    def findAllRecipes(self, recipes: List[str], ingredients: List[List[str]], supplies: List[str]) -> List[str]:
        graph = collections.defaultdict(list)
        indegree = collections.defaultdict(int)

        for recipe, ingredientsList in zip(recipes, ingredients):
            indegree[recipe] = len(ingredientsList)
            for ing in ingredientsList:
                graph[ing].append(recipe)

        queue = collections.deque(supplies)
        ans = []
        recipeSet = set(recipes)

        while queue:
            curr = queue.popleft()
            if curr in recipeSet:
                ans.append(curr)

            for nextRecipe in graph[curr]:
                indegree[nextRecipe] -= 1
                if indegree[nextRecipe] == 0:
                    queue.append(nextRecipe)

        return ans

class Solution(object):
    def firstPalindrome(self, words):
        """
        :type words: List[str]
        :rtype: str
        """
        for i in range(0, len(words)):
            word = words[i]
            left, right = 0, len(word)-1
            is_palindromic = True

            while left < right:
                if word[left] != word[right]:
                    is_palindromic = False
                    break
                elif word[left] == word[right]:
                    left += 1
                    right -= 1

            if is_palindromic == True:
                return word
        return ""

