class Solution:
    def maxNumOfMarkedIndices(self, nums: List[int]) -> int:
        nums.sort()
        n = len(nums)
        left, right = 0, n//2
        ops = 0
        while left < n//2 and right < n:
            if 2 * nums[left] <= nums[right]:
                ops += 2
                left += 1
                right += 1
            else:
                right += 1
        return ops

class Solution:
    def leftRightDifference(self, nums: List[int]) -> List[int]:
        n = len(nums)
        left = [0] * (n+1)
        for i in range(1, n):
            left[i] = left[i-1] + nums[i-1]
        left = left[0:n]

        right = [0] * (n+1)
        for i in range(n-1, -1, -1):
            right[i] = right[i+1] + nums[i]
        right = right[1:]

        res = []
        for i in range(0, n):
            res.append(abs(left[i]-right[i]))
        return res

class Solution:
