class Solution:
    def earliestFinishTime(self, landStartTime: List[int], landDuration: List[int], waterStartTime: List[int], waterDuration: List[int]) -> int:
        min_curr = float('inf')
        for i in range(0, len(landStartTime)):
            for j in range(0, len(waterStartTime)):
                land_finish = landStartTime[i] + landDuration[i]
                water_finish = waterStartTime[j] + waterDuration[j]

                res1 = max(land_finish, waterStartTime[j]) + waterDuration[j]
                res2 = max(water_finish, landStartTime[i]) + landDuration[i]

                curr = min(res1, res2)
                min_curr = min(min_curr, curr)
        return min_curr

class Solution:
    def earliestFinishTime(self, landStartTime: List[int], landDuration: List[int], waterStartTime: List[int], waterDuration: List[int]) -> int:
        i, j = 0, 0
        min_finish = float('inf')

        for i in range(0, len(landStartTime)):
            for j in range(0, len(waterStartTime)):
                land_finish = landStartTime[i] + landDuration[i]
                water_finish = waterStartTime[j] + waterDuration[j]

                total_finish1 = max(land_finish, waterStartTime[j]) + waterDuration[j]
                total_finish2 = max(water_finish, landStartTime[i]) + landDuration[i]

                curr = min(total_finish1, total_finish2)
                min_finish = min(min_finish, curr)

        return min_finish

class Solution:
    def maxKDistinct(self, nums: List[int], k: int) -> List[int]:
        sett = list(set(nums))
        sett.sort(reverse=True)
        res = []
        for i in range(0, len(sett)):
            if i < k:
                res.append(sett[i])
            else:
                break
        return res
